        CK(0x6882);
        D = rd16(U);                                 /* L6882 */
        U = (uint16_t)(U + 2);
        wr16(0+M_GD, D);                             /* L6884  X */
        D = rd16(U);                                 /* L6887 */
        U = (uint16_t)(U + 2);
        wr16(2+M_GD, D);                             /* L6889  Y */
