        CYC(16);
        JSR(mgowt);                                  /* L6899 */
        D = rd16(M_XP);                              /* L689C */
        wr16((uint16_t)(X + MS_GDXR), D);            /* L689F */
        D = rd16(M_YP);                              /* L68A1 */
        wr16((uint16_t)(X + MS_GDYR), D);            /* L68A4 */
        D = rd16(M_ZP);                              /* L68A7 */
