/* JBJGDRW ($6AA0, bank 1) - Draw ground type object BJ_ID: its TDRWLN entry must begin with type byte 1 (else SWI); jumps to the
 *   code that follows that byte (direct executing)
 */
void jbjgdrw(void)
{
    CK(0x6AA0);
    X = TDRWLN;                                      /* L6AA0 */
    B = M8(BJ_ID);                                   /* L6AA3  PULL IN OBJECTS IDENTIFICATION */
    B = (uint8_t)(B << 1);                           /* L6AA5 */
    U = rd16((uint16_t)(X + (int8_t)B));             /* L6AA6 */
    B = rd8(U);                                      /* L6AA8 */
    U = (uint16_t)(U + 1);
    CYC(26);
    if (B != 0x01) {                                 /* L6AAC  IFNE  ?GROUND TYPE OBJECT? */
        CYC(19);
        sw_swi(0x6AAE);                              /* L6AAE  OOPS, NOT CORRECT TYPE */
    }
    CYC(3);
    call_rom(U); return;                             /* L6AAF  GO DO IT */
}

